function teamNeeds(team){return Object.keys(TARGET).filter(pos=>posCount(team,pos)<TARGET[pos])}
function myNeed(pos){return Math.max(0,(TARGET[pos]||0)-posCount(myTeam(),pos))}
function pickSlot(pick){const round=Math.ceil(pick/12);const posInRound=pick-(round-1)*12;const slot=round%2===1?posInRound:13-posInRound;return slot-1}
function isMyTurn(){return currentPick<=MAX_PICK&&pickSlot(currentPick)===(draftPos-1)}
function canDraftNow(){return liveDraftMode?currentPick<=MAX_PICK:isMyTurn()}
function nextMyPick(from){let p=from;while(p<=MAX_PICK&&pickSlot(p)!==(draftPos-1))p++;return p<=MAX_PICK?p:null}
