  reportEl.innerHTML=`<div class="mini" style="color:#ff8190">${escHtml(liveSyncState.hint||"")}</div><div class="mini" style="margin-top:6px;color:#68778e">Raw error: ${escHtml(liveSyncState.error||"unknown")}</div>`;
