async function syncLiveData(){
 const btn=document.getElementById("liveSyncBtn");
 const statusEl=document.getElementById("liveSyncStatus");
 const reportEl=document.getElementById("liveSyncReport");
 if(btn)btn.disabled=true;if(btn)btn.textContent="SYNCING...";
 if(statusEl)statusEl.textContent="Fetching active NFL player data...";
 if(reportEl)reportEl.innerHTML="";
 const controller=new AbortController();
 const timeoutId=setTimeout(()=>controller.abort(),25000);
 try{
  const res=await fetch("https://api.sleeper.app/v1/players/nfl?active=true",{signal:controller.signal});
  clearTimeout(timeoutId);
  if(!res.ok)throw new Error(`HTTP ${res.status}`);
  const json=await res.json();
  const index=new Map();
  Object.values(json).forEach(entry=>{
   if(!entry||!entry.last_name)return;
   const positions=Array.isArray(entry.fantasy_positions)?entry.fantasy_positions:[entry.position];
   const pos=positions.find(x=>["QB","RB","WR","TE","K","DEF"].includes(x));
   if(!pos)return;
   const key=normalizeName(`${entry.first_name||""} ${entry.last_name||""}`);
   if(key)index.set(key,{...entry,pos});
  });
  const STATUS_MAP={Questionable:"questionable",Doubtful:"doubtful",Out:"out",IR:"ir",PUP:"ir",Sus:"out",COV:"questionable",NA:"out"};
  let matched=0,injuries=0,added=0;
  const mismatches=[];
  const existing=new Map(DATA.map(p=>[normalizeName(p.name),p]));
  DATA.forEach(p=>{
   const entry=index.get(normalizeName(p.name));
   if(!entry)return;
   matched++;
   const mapped=STATUS_MAP[entry.injury_status]||"healthy";
   if(mapped==="healthy")delete playerStatus[p.name];else playerStatus[p.name]=mapped;
   if(mapped!=="healthy")injuries++;
   if(entry.team&&entry.team!==p.team)mismatches.push({name:p.name,ours:p.team,live:entry.team});
   p.team=entry.team||"FA";
   p.active=true;
  });
  index.forEach((entry,key)=>{
   if(existing.has(key))return;
   const name=`${entry.first_name||""} ${entry.last_name||""}`.trim();
   if(!name)return;
   DATA.push({name,pos:entry.pos,team:entry.team||"FA",adp:null,espn:999,sleeper:999,fp:999,walter:999,tier:"Waiver",active:true,sleeperId:entry.player_id||null});
   added++;
  });
  REPLACEMENT_LEVELS=null;
  liveSyncState={status:"done",timestamp:new Date().toISOString(),matched,total:DATA.length,added,injuries,mismatches};
  renderLiveSyncStatus(); render(); saveState();
  showToast(`Roster refreshed — ${added} active player(s) added`);
 }catch(e){
  clearTimeout(timeoutId);
  const rawName=e&&e.name?e.name:"Error"; const rawMsg=e&&e.message?e.message:String(e);
  const hint=rawName==="AbortError"?"Request timed out after 25s. Try again on wifi.":(rawName==="TypeError"&&/fetch|network|load/i.test(rawMsg)?"The browser likely blocked the cross-origin request. Open the dashboard over HTTPS (not a file:// preview).":"Unexpected error — see raw details below.");
  liveSyncState={status:"error",timestamp:new Date().toISOString(),error:`${rawName}: ${rawMsg}`,hint};
  renderLiveSyncStatus(); saveState(); showToast("Live roster sync failed");
 }finally{ if(btn){btn.disabled=false;btn.textContent="SYNC NOW";} }
}

/* ---------- real NFL schedule sync ---------- */
function normalizeScheduleResponse(payload){
 const rows=Array.isArray(payload)?payload:(Array.isArray(payload?.games)?payload.games:(Array.isArray(payload?.schedule)?payload.schedule:[]));
 const map={};
 rows.forEach(row=>{
  const season=Number(row.season??row.seasonYear??2026);
  const week=Number(row.week??row.weekNumber??row.scoringPeriodId);
  const type=String(row.gameType??row.game_type??row.seasonType??"REG").toUpperCase();
  const home=String(row.homeTeam??row.home_team??row.home??"").toUpperCase();
  const away=String(row.awayTeam??row.away_team??row.away??"").toUpperCase();
  if(season!==2026||!Number.isInteger(week)||week<1||week>18||!home||!away)return;
  if(type&&type!=="REG")return;
  [[home,away],[away,home]].forEach(([team,opp])=>{
   map[team]??={};
   map[team][week]={week,opponent:opp,home,away,bye:false,date:row.gameDate??row.game_date??null};
  });
 });
 // A team with no game in a regular-season week is on bye.
 Object.keys(REAL_BYE_WEEKS_2026).forEach(team=>{
  map[team]??={};
  for(let w=1;w<=18;w++)if(!map[team][w])map[team][w]={week:w,bye:true};
 });
 return map;
}
