/* ---------- rendering: draft page ---------- */
function getStarterSplit(team){
 const order=["QB","RB","RB","WR","WR","TE","DEF","K"];
 const used=[];
 const starters=order.map(pos=>{
  const p=team.roster.find(x=>x.pos===pos&&!used.includes(x.name));
  if(p)used.push(p.name);
  return {pos,p};
 });
 const bench=team.roster.filter(x=>!used.includes(x.name));
 return {starters,bench};
}
function renderRoster(){
 const team=myTeam();
 const {starters,bench}=getStarterSplit(team);
 const order=starters.map(s=>s.pos);
 document.getElementById("roster").innerHTML=starters.map(({pos,p},i)=>{
  const totalForPos=order.filter(x=>x===pos).length;
  const countBefore=order.slice(0,i).filter(x=>x===pos).length;
  const label=pos+(totalForPos>1?" "+(countBefore+1):"");
  return `<div class="slot"><b>${label}</b><span class="${p?"":"need"}">${p?p.name:"OPEN"}</span></div>`;
 }).join("");
 document.getElementById("bench").innerHTML=bench.length?`<div class="smallcaps" style="margin-top:12px">Bench (${bench.length})</div><div class="mini" style="margin-top:6px;line-height:1.9">${bench.map(p=>`${p.name} <span style="color:#68778e">(${p.pos})</span>`).join(" · ")}</div>`:"";
}
function reason(p){
 const team=myTeam();
 const d=draftDecisionScore(p,team);
 const bits=[];
 if(p.adp!=null)bits.push(`ADP ${p.adp}`);
 if(d.cliff.strength>=55)bits.push(d.cliff.label);
 if(d.loss.expectedLoss>=45)bits.push(`${d.loss.survival}% survival`);
 if(d.need>=88)bits.push(`fills ${p.pos} need`);
 if(d.scarcity>=60)bits.push(`${p.pos} scarcity/run`);
 if(!bits.length)bits.push("best overall market option");
 return bits.join(" · ");
}
function takeNowVsWait(p,team){
 const d=draftDecisionScore(p,team);
 const loss=d.loss;
 const survival=loss.survival;
 const takeNow=Math.max(0,Math.min(100,d.score*0.72+survival*0.08+d.cliff.strength*0.10+d.need*0.05+d.scarcity*0.05));
 const wait=Math.max(0,Math.min(100,takeNow-(100-survival)*0.38));
 return {takeNow:Math.round(takeNow*10)/10,wait:Math.round(wait*10)/10,survive:survival,cliff:d.cliff,loss};
}
function breakdownBars(p,team){
 return scoreBreakdown(p,team).map(b=>`<div class="sb-row"><span class="sb-label">${b.label}</span><div class="sb-bar"><i style="width:${b.pct}%"></i></div></div>`).join("");
}
function renderRec(){
 const p=bestPlayer(); if(!p)return;
 const canDraft=canDraftNow();
 const team=myTeam();
 const tw=takeNowVsWait(p,team);
 const before=teamsBeforeMyNextPick();
 const alternatives=pickCandidates(team).filter(x=>x.name!==p.name).slice().sort((a,b)=>decisionCompare(a,b,team));
 const next=alternatives[0];
 const impact=next?Math.max(0,tw.takeNow-draftDecisionScore(next,team).score):0;
 const cliff=tw.cliff;
 const impactLabel=next?`+${impact.toFixed(1)} draft impact vs ${next.name}`:"No close alternative";
 document.getElementById("recommendation").innerHTML=`<div style="margin-top:9px"><div class="rec-top"><div><div class="rec-name">${p.name}</div><div class="rec-sub">${p.pos} · ${p.team} · Market ADP ${p.adp??"—"} · Expert ${p.expert?.toFixed(1)??"—"}</div></div><div class="score">${p.score>=0?"+":""}${p.score.toFixed(1)}</div></div><div class="why"><span class="tag">${p.action}</span><span class="tag">${cliff.strength>=55?"⚠️ TIER CLIFF":"Tier stable"}</span><span class="tag">${tw.loss.survival}% survive to next pick</span><span class="tag">${tw.loss.expectedLoss} loss risk</span><span class="tag">${impactLabel}</span><span class="tag">Sug. Rd ${p.suggestedRound??"—"}</span></div><p style="color:#9aa8bd;font-size:11px;line-height:1.6"><b>Why now:</b> ${reason(p)}. ${cliff.next?`Next ${p.pos}: ${cliff.next.name} (ADP ${cliff.next.adp}).`:"This is the last modeled player in this position tier."}</p>
 <div class="tnw"><div class="tnw-box"><span class="mini">TAKE NOW</span><b class="positive">${tw.takeNow}</b></div><div class="tnw-box"><span class="mini">WAIT</span><b class="${tw.wait<tw.takeNow-15?"negative":""}">${tw.wait}</b></div><div class="tnw-box"><span class="mini">SURVIVAL (${before.length} picks)</span><b class="${tw.survive<30?"negative":tw.survive<60?"amber":"positive"}">${tw.survive}%</b></div></div>
 ${before.length?`<div class="mini" style="margin-top:9px">Picking before your next turn: ${before.map(b=>escHtml(b.teamName)).join(", ")}</div>`:""}
 <div class="scorebreak"><div class="smallcaps" style="margin:11px 0 6px">Decision breakdown</div>${breakdownBars(p,team)}</div>
 <div class="rec-actions"><button class="primary" ${canDraft?"":"disabled"} onclick="draftPlayer('${esc(p.name)}')">${canDraft?(liveDraftMode?"LOG ":"DRAFT ")+p.name.toUpperCase():(currentPick>MAX_PICK?"DRAFT COMPLETE":"WAIT FOR YOUR TURN")}</button></div></div>`;
 document.getElementById("bestValue").textContent=p.name;document.getElementById("bestValueMeta").textContent=`${impactLabel}`;
}
