 a.sort((x,y)=>sort==="score"?y.score-x.score:sort==="best"?recommendationComparator(x,y):sort==="pts"?y.seasonPts-x.seasonPts:sort==="adp"?((x.adp??999)-(y.adp??999)||(y.seasonPts-x.seasonPts)):sort==="rank"?x.expert-y.expert:sort==="ceil"?(x.ceil??999)-(y.ceil??999):y.gap-x.gap);
 const statusTitle=name=>{const st=getStatus(name);return st==="healthy"?"Mark injury status":`Status: ${STATUS_META[st].label} (tap to change)`};
