 const rowHtml=(p,sel,side)=>`<label class="prow"><input type="checkbox" ${sel.has(p.name)?"checked":""} onchange="toggleTradeSel('${side}','${esc(p.name)}')"><span class="pname">${p.name} <span class="mini">${p.pos}</span></span><span class="pval">value ${tradeValue(p)}</span></label>`;
