 document.getElementById("tradeListB").innerHTML=teamB.roster.length?teamB.roster.map(p=>rowHtml(p,tradeSelB,"B")).join(""):`<div class="mini" style="padding-top:8px">No roster yet — draft or auto-sim picks first.</div>`;
