/* ---------- master render ---------- */
function renderAlert(){
 const banner=document.getElementById("alertBanner");
 const icon=document.getElementById("alertIcon"),title=document.getElementById("alertTitle"),text=document.getElementById("alertText");
 const roster=myTeam().roster;
 const byeCounts={};
 roster.forEach(p=>{const w=byeWeek(p.team);byeCounts[w]=(byeCounts[w]||0)+1});
 let maxWeek=null,maxCount=0;
 Object.entries(byeCounts).forEach(([w,c])=>{if(c>maxCount){maxCount=c;maxWeek=w}});
 if(maxCount>=3){
  banner.style.display="flex";
  icon.textContent="⚠️";
  title.textContent=`Bye-week cluster: Week ${maxWeek}`;
  text.textContent=`You have ${maxCount} players on bye in Week ${maxWeek}. Worth diversifying with remaining picks or a waiver swap.`;
 }else if(currentPick>MAX_PICK){
  banner.style.display="flex";
  icon.textContent="🏁";
  title.textContent="Draft complete";
  text.textContent="Check your draft grade above, or head to Trade/Waivers to keep improving the roster.";
 }else{
  let hottest=null;
  ["QB","RB","WR","TE"].forEach(pos=>{
   const pressure=positionRunPressure(pos);
   if(pressure>=0.4&&(!hottest||pressure>hottest.pressure))hottest={pos,pressure};
  });
  if(hottest){
   const recentCount=feed.slice(-12).filter(f=>f.pos===hottest.pos).length;
   const bestRemaining=available().filter(p=>p.pos===hottest.pos).sort((a,b)=>b.seasonPts-a.seasonPts)[0];
   const nmp=nextMyPick(isMyTurn()?currentPick+1:currentPick);
   const survive=bestRemaining&&nmp?survivalProb(bestRemaining,nmp-1):null;
   banner.style.display="flex";
   icon.textContent="🔥";
   title.textContent=`${hottest.pos} run detected`;
   text.textContent=`${recentCount} ${hottest.pos}${recentCount!==1?"s":""} drafted in the last 12 picks.${bestRemaining?` Best remaining: ${bestRemaining.name}${survive!=null?` — ${survive}% chance to survive to your next pick.`:""}`:""}`;
  }else{
   banner.style.display="none";
  }
 }
}
const ROUND_TARGET_LABELS={
 1:"Elite RB/WR",2:"RB/WR",3:"RB/WR",4:"RB/WR",5:"RB/WR or elite TE",
 6:"Fill major need (TE/QB/RB/WR)",7:"Core players (QB/TE/RB/WR)",
 8:"Best value",9:"Best value",10:"Best value / upside",
 11:"RB/WR upside (bench)",12:"RB/WR upside (bench)",13:"RB/WR upside (bench)",
 14:"Skill-player bench / upside",15:"DEF only",16:"K only"
};
function roundByRoundGroups(){
 const groups={};
 for(let r=1;r<=ROUNDS;r++)groups[r]=[];
 available().forEach(p=>{
  let r;
  if(p.pos==="DEF")r=ROUNDS-1;
  else if(p.pos==="K")r=ROUNDS;
  else{
   r=p.adp?Math.max(1,Math.ceil(p.adp/12)):ROUNDS-2;
   r=Math.min(r,ROUNDS-2);
  }
  groups[r].push(p);
 });
 Object.values(groups).forEach(list=>list.sort((a,b)=>(a.adp??999)-(b.adp??999)));
 return groups;
}
function tierBuckets(posFilter){
 const team=myTeam();
 let pool=available();
 if(posFilter&&posFilter!=="ALL")pool=pool.filter(p=>p.pos===posFilter);
 const scored=pool.map(p=>({p,rs:recommendScore(p,team)})).sort((a,b)=>b.rs-a.rs);
 const buckets={Elite:[],Great:[],Good:[],Okay:[],Avoid:[]};
 scored.forEach(x=>{
  if(x.rs>=20)buckets.Elite.push(x);
  else if(x.rs>=8)buckets.Great.push(x);
  else if(x.rs>=0)buckets.Good.push(x);
  else if(x.rs>=-8)buckets.Okay.push(x);
  else buckets.Avoid.push(x);
 });
 return buckets;
}
const TIER_META={
 Elite:{cls:"tier-elite",icon:"💎"},
 Great:{cls:"tier-great",icon:"🟢"},
 Good:{cls:"tier-good",icon:"🔵"},
 Okay:{cls:"tier-okay",icon:"🟡"},
 Avoid:{cls:"tier-avoid",icon:"🔴"},
};
function tierForScore(rs){
 if(rs>=20)return"Elite";
 if(rs>=8)return"Great";
 if(rs>=0)return"Good";
 if(rs>=-8)return"Okay";
 return"Avoid";
}
