 teams.forEach(t=>{const te=posCount(t,"TE"),qb=posCount(t,"QB"),def=posCount(t,"DEF"),k=posCount(t,"K");checks.push({te,qb,def,k,starter:Object.keys(STARTER_TARGET).every(pos=>posCount(t,pos)>=STARTER_TARGET[pos])});});
 const noHoard=checks.filter(x=>x.te<=2&&x.qb<=2).length;
