function ensureManagerPlayer(spec){
 let p=DATA.find(x=>normalizeName(x.name)===normalizeName(spec.name));
 if(!p){p={name:spec.name,pos:spec.pos,team:spec.team,adp:spec.pick,espn:999,sleeper:999,fp:999,walter:999,tier:"Bench"};DATA.push(p)}
 p.pos=spec.pos;p.team=spec.team;p.finalDraftPick=spec.pick;
 return p;
}
