 me.roster=FINAL_ROSTER.map(x=>{const p=ensureManagerPlayer(x);return {...p,draftOverall:x.pick,draftRound:Math.ceil(x.pick/12),draftTeamIdx:draftPos-1}});
 drafted=new Set(me.roster.map(p=>p.name));
