function mgrWeek(){return Number(document.getElementById("mgrWeek")?.value||plannerWeek||1)}
function mgrProj(p,week){const live=syncedWeeklyProj(p,week);return Number.isFinite(live)?live:projPts(p)}
function managerEligible(p,week){return !isInjuredOut(p.name)&&byeWeek(p.team)!==week}
function optimizeManagerLineup(team,week){
 const roster=team.roster||[]; const used=new Set(); const take=(pos,n)=>roster.filter(p=>p.pos===pos&&!used.has(p.name)&&managerEligible(p,week)).sort((a,b)=>mgrProj(b,week)-mgrProj(a,week)).slice(0,n).map(p=>{used.add(p.name);return p});
 const out=[]; const qb=take("QB",1)[0]||null; out.push({slot:"QB",p:qb}); take("RB",2).forEach((p,i)=>out.push({slot:`RB${i+1}`,p})); take("WR",2).forEach((p,i)=>out.push({slot:`WR${i+1}`,p})); out.push({slot:"TE",p:take("TE",1)[0]||null}); out.push({slot:"DEF",p:take("DEF",1)[0]||null}); out.push({slot:"K",p:take("K",1)[0]||null});
 return {starters:out,bench:roster.filter(p=>!used.has(p.name))};
}
function managerGrade(team){
 const raw=computeTeamFit(team); return Math.max(0,Math.min(100,Math.round(raw)));
}
function managerRank(){
 const otherFilled=teams.filter((t,i)=>i!==draftPos-1 && (t.roster||[]).length>0).length;
 if(otherFilled<2)return null;
 const ranked=rankedTeams(); const i=ranked.findIndex(x=>x.i===draftPos-1); return i>=0?i+1:null;
}
function managerActions(team,week,lineup){
 const a=[]; const starters=lineup.starters.filter(x=>x.p).map(x=>x.p); const bench=lineup.bench;
 team.roster.forEach(p=>{const st=getStatus(p.name); if(st!=="healthy")a.push({icon:st==="out"||st==="ir"?"🚑":"⚠️",title:`${p.name} is ${STATUS_META[st].label}`,body:"Review the roster before kickoff and replace if necessary.",cls:"manager-bad"})});
 const byes=team.roster.filter(p=>byeWeek(p.team)===week); if(byes.length)a.push({icon:"🛌",title:`Bye week: ${byes.length} roster player${byes.length>1?'s':''}`,body:byes.map(p=>p.name).join(", "),cls:"manager-alert"});
 const weak=starters.filter(p=>p.pos!=="DEF"&&p.pos!=="K"&&mgrProj(p,week)<(p.pos==="QB"?16:p.pos==="TE"?9:12)); if(weak.length)a.push({icon:"📉",title:"Starter-quality check",body:`${weak.map(p=>p.name).join(", ")} project below your normal weekly baseline.`,cls:"manager-alert"});
 const benchUpside=bench.filter(p=>p.pos!=="K"&&p.pos!=="DEF").sort((x,y)=>mgrProj(y,week)-mgrProj(x,week))[0]; if(benchUpside)a.push({icon:"💡",title:"Bench upside",body:`${benchUpside.name} is your top non-starter upside option at ${mgrProj(benchUpside,week).toFixed(1)} projected points.`,cls:"manager-good"});
 if(!a.length)a.push({icon:"✅",title:"No urgent action",body:"Your current optimized lineup has no obvious health or bye-week conflicts.",cls:"manager-good"});
 return a.slice(0,6);
}
function renderManager(){
 const team=myTeam(); if(!team)return;
 const week=mgrWeek(); plannerWeek=week;
 const lineup=optimizeManagerLineup(team,week); const rank=managerRank(); const grade=managerGrade(team); const starters=lineup.starters.filter(x=>x.p);
 const proj=starters.reduce((s,x)=>s+mgrProj(x.p,week),0);
 const rankEl=document.getElementById("mgrRank"); if(rankEl)rankEl.textContent=rank?`#${rank}`:"—";
 const rm=document.getElementById("mgrRankMeta"); if(rm)rm.textContent=rank?`of ${LEAGUE_TEAMS} teams`:"manual league sync needed";
 const ge=document.getElementById("mgrGrade"); if(ge)ge.textContent=`${grade}`;
 const gm=document.getElementById("mgrGradeMeta"); if(gm)gm.textContent=grade>=90?"Elite roster build":grade>=80?"Strong playoff build":grade>=70?"Competitive roster":"Needs work";
 const pe=document.getElementById("mgrProj"); if(pe)pe.textContent=proj.toFixed(1);
 const pm=document.getElementById("mgrProjMeta"); if(pm)pm.textContent=projectionSourceIsLive(week)?`Week ${week} · FantasyPros PPR`:"Fallback weekly model";
 const oe=document.getElementById("mgrOpponent"); if(oe)oe.textContent="—";
 const om=document.getElementById("mgrOpponentMeta"); if(om)om.textContent="12-team matchup model";
 const ws=document.getElementById("mgrWeek"); if(ws&&!ws.options.length)for(let w=1;w<=18;w++)ws.insertAdjacentHTML("beforeend",`<option value="${w}">Week ${w}</option>`); if(ws)ws.value=week;
 const lb=document.getElementById("mgrLineup"); if(lb)lb.innerHTML=`<table class="lineup-table"><tbody>${lineup.starters.map(x=>{const p=x.p;const isBye=p&&byeWeek(p.team)===week;return `<tr><td>${x.slot}</td><td>${p?`<div class="lineup-player">${escHtml(p.name)} ${statusBadge(p.name)}</div><div class="lineup-sub">${p.team} · ${weekMatchupLabel(p,week)}</div>`:`<span class="need">Needs ${x.slot}</span>`}</td><td>${p?`<span class="manager-badge ${isBye?"mb-bye":"mb-start"}">${isBye?"BYE":mgrProj(p,week).toFixed(1)+" PTS"}</span>`:"—"}</td></tr>`}).join("")}</tbody></table><div class="mini" style="margin-top:9px">Bench: ${lineup.bench.map(p=>p.name).join(", ")||"none"}</div>`;
 const acts=managerActions(team,week,lineup); const ab=document.getElementById("mgrActions"); if(ab)ab.innerHTML=acts.map(a=>`<div class="action-item ${a.cls}"><div class="ai-icon">${a.icon}</div><div><b>${escHtml(a.title)}</b><span>${escHtml(a.body)}</span></div></div>`).join("");
 const counts={QB:posCount(team,"QB"),RB:posCount(team,"RB"),WR:posCount(team,"WR"),TE:posCount(team,"TE"),DEF:posCount(team,"DEF"),K:posCount(team,"K")};
 const strat=[]; if(counts.RB<3)strat.push(["🏃","RB depth","You have limited RB insulation behind Bijan/TreVeyon. Prioritize contingent upside on waivers."]); else strat.push(["🏃","RB depth","Your RB room has enough depth to avoid chasing low-ceiling replacements."]); if(counts.WR>=5)strat.push(["📡","WR surplus","Seven WRs give you trade leverage. Shop the back-end of the room if a starting RB is available."]); if(counts.QB===1)strat.push(["🧠","QB discipline","One QB is exactly what you want in this 1-QB format; stream only when the matchup calls for it."]); if(counts.TE===1)strat.push(["🎯","TE advantage","Bowers is your locked-in starter. Do not burn a roster spot on another TE without a clear reason."]); strat.push(["🛡️","Roster rule","DEF/K are set; every remaining roster decision should optimize skill-player points."]);
 const st=document.getElementById("mgrStrategy"); if(st)st.innerHTML=strat.map(x=>`<div class="action-item manager-good"><div class="ai-icon">${x[0]}</div><div><b>${x[1]}</b><span>${x[2]}</span></div></div>`).join("");
 const snap=document.getElementById("mgrSnapshot"); if(snap)snap.innerHTML=`<div class="action-list"><div class="action-item"><div><b>${team.roster.length}/${ROSTER_SIZE} rostered</b><span>${counts.RB} RB · ${counts.WR} WR · ${counts.TE} TE · ${counts.QB} QB · ${counts.DEF} DEF · ${counts.K} K</span></div></div><div class="action-item"><div><b>Best weekly core</b><span>${starters.slice(0,6).map(x=>x.p?.name).filter(Boolean).join(" · ")}</span></div></div><div class="action-item"><div><b>Bye concentration</b><span>${Object.entries(team.roster.reduce((o,p)=>{const w=byeWeek(p.team);if(w)o[w]=(o[w]||0)+1;return o},{})).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>`Wk ${x[0]}: ${x[1]}`).join(" · ")||"None"}</span></div></div></div>`;
 const moves=[]; const waiverCandidates=available().filter(p=>p.pos!=="K"&&p.pos!=="DEF").sort((a,b)=>tradeValue(b)-tradeValue(a)).slice(0,3); moves.push(`<div class="action-item manager-good"><div class="ai-icon">🎯</div><div><b>Priority waiver search</b><span>Use Waivers to identify RB contingency backs and WR breakout candidates; current roster already has strong WR depth.</span></div></div>`); moves.push(`<div class="action-item"><div class="ai-icon">🔄</div><div><b>Trade posture</b><span>Do not sell Bijan or Bowers cheaply. Your most movable assets are the WR5–WR7 tier and surplus RB depth.</span></div></div>`); moves.push(`<div class="action-item"><div class="ai-icon">📅</div><div><b>Weekly routine</b><span>Check Manager → Matchups → Waivers by Tuesday, then re-check injuries and inactives before each player's kickoff.</span></div></div>`);
 const mv=document.getElementById("mgrMoves"); if(mv)mv.innerHTML=moves.join("");
}
function renderRosters(){
 const sel=document.getElementById("rosterTeamSelect"); if(!sel)return;
 const cur=Number(sel.value||draftPos-1); if(sel.options.length!==teams.length){sel.innerHTML=teams.map((t,i)=>`<option value="${i}">${escHtml(t.name)}</option>`).join("")}; sel.value=String(cur);
 const t=teams[cur]||teams[draftPos-1]; const head=document.getElementById("rosterHeader"); const grid=document.getElementById("rosterGrid");
 const slots=["QB","RB","RB","WR","WR","TE","DEF","K","BENCH","BENCH","BENCH","BENCH","BENCH","BENCH","BENCH","BENCH"];
 const used=[]; const html=slots.map((slot,i)=>{let p=null;if(slot!=="BENCH")p=t.roster.find(x=>x.pos===slot&&!used.includes(x.name));else p=t.roster.find(x=>!used.includes(x.name));if(p)used.push(p.name);return `<div class="roster-slot"><div class="rs-pos">${slot}${slot!=="BENCH"&&slots.slice(0,i).filter(x=>x===slot).length?" "+(slots.slice(0,i).filter(x=>x===slot).length+1):""}</div><div class="rs-name">${p?escHtml(p.name):"Empty"}</div><div class="rs-meta">${p?`${p.pos} · ${p.team} ${statusBadge(p.name)}`:"Available roster spot"}</div></div>`}).join("");
 if(head)head.innerHTML=`<div class="mini"><b>${escHtml(t.name)}</b> · ${t.roster.length}/${ROSTER_SIZE} players ${cur===draftPos-1?"· YOUR TEAM":""}</div>`;
 if(grid)grid.innerHTML=html;
 const alerts=[]; t.roster.forEach(p=>{const st=getStatus(p.name);if(st!=="healthy")alerts.push(`<div class="action-item manager-bad"><div><b>${escHtml(p.name)} — ${STATUS_META[st].label}</b><span>Review before lineup lock.</span></div></div>`)});
 if(!alerts.length)alerts.push(`<div class="manager-empty">No manually flagged injuries/status issues for this roster.</div>`); document.getElementById("rosterAlerts").innerHTML=alerts.join("");
}
document.getElementById("mgrWeek")?.addEventListener("change",e=>{plannerWeek=Number(e.target.value)||1;renderManager();saveState()});
document.getElementById("rosterTeamSelect")?.addEventListener("change",()=>renderRosters());


/* ---------- league activity / snapshots ---------- */
function recordRosterTransaction(type,teamIdx,player,details=""){activityLog.unshift({id:Date.now()+Math.random(),timestamp:Date.now(),type,team:teams[teamIdx]?.name||`Team ${teamIdx+1}`,teamIdx,player:player?.name||String(player||""),pos:player?.pos||"",nflTeam:player?.team||"",details});activityLog=activityLog.slice(0,500);}
function renderLeagueActivity(){const s=document.getElementById("leagueActivitySummary"),l=document.getElementById("leagueActivityLog");if(!s||!l)return;const total=teams.reduce((n,t)=>n+(t.roster||[]).length,0);s.innerHTML=`<div class="mini-list"><span class="mini-pill">${teams.filter(t=>(t.roster||[]).length).length}/12 teams entered</span><span class="mini-pill">${total} rostered players</span><span class="mini-pill">${activityLog.length} logged moves</span></div>`;l.innerHTML=activityLog.length?activityLog.slice(0,30).map(x=>`<div class="flagrow"><span class="fi">${x.type==="ADD"?"➕":x.type==="DROP"?"➖":"📸"}</span><div><b>${escHtml(x.team)}</b><span>${escHtml(x.type)} ${escHtml(x.player)}${x.details?` · ${escHtml(x.details)}`:""}<br><small>${new Date(x.timestamp).toLocaleString()}</small></span></div></div>`).join(""):`<div class="mini">No roster activity has been logged yet. Manual adds/drops will appear here automatically.</div>`;}
function exportLeagueSnapshot(){const payload={appVersion:"24.3",exportedAt:new Date().toISOString(),league:{teams:teams.map(t=>({id:t.id,name:t.name,record:t.record||{wins:0,losses:0,ties:0,pf:0,pa:0},roster:(t.roster||[]).map(p=>({name:p.name,pos:p.pos,team:p.team,status:getStatus(p.name)}))}))},activityLog,weeklyProjectionState:projectionSyncState||null};const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}));a.download=`draft-command-center-league-snapshot-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast("League snapshot exported");}
function importLeagueSnapshot(file){const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(!p?.league?.teams||p.league.teams.length!==12)throw new Error("Snapshot must contain 12 teams");teams=p.league.teams.map((t,i)=>({...t,id:i,roster:(t.roster||[]).map(x=>DATA.find(p=>normalizeName(p.name)===normalizeName(x.name))||{...x,active:true})}));activityLog=Array.isArray(p.activityLog)?p.activityLog:[];drafted=new Set(teams.flatMap(t=>(t.roster||[]).map(p=>p.name)));saveState();render();showToast("League snapshot imported");}catch(e){showToast(`Snapshot import failed: ${e.message||e}`);}};r.readAsText(file);}
document.getElementById("exportLeagueSnapshot")?.addEventListener("click",exportLeagueSnapshot);document.getElementById("importLeagueSnapshot")?.addEventListener("change",e=>{if(e.target.files?.[0])importLeagueSnapshot(e.target.files[0]);});document.getElementById("clearActivityLog")?.addEventListener("click",()=>{if(confirm("Clear the league activity log? Rosters will not be changed.")){activityLog=[];saveState();renderLeagueActivity();}});
/* ---------- v24 mobile roster builder ---------- */
let builderTeamIdx=draftPos-1;
function builderTeams(){return teams.length===12?teams:[]}
function builderRender(){
 const sel=document.getElementById("rosterTeamSelect");if(!sel)return;
 const ts=builderTeams();
 builderTeamIdx=Math.max(0,Math.min(ts.length-1,Number(sel.value!==""?sel.value:builderTeamIdx)||0));
 sel.innerHTML=ts.map((t,i)=>`<option value="${i}">${escHtml(t.name||`Team ${i+1}`)}</option>`).join("");
 sel.value=String(builderTeamIdx);
 const t=ts[builderTeamIdx]||{name:"Team",roster:[]};
 const tn=document.getElementById("builderTeamName");if(tn&&document.activeElement!==tn)tn.value=t.name||`Team ${builderTeamIdx+1}`;
 const title=document.getElementById("builderRosterTitle");if(title)title.textContent=`${t.name||`Team ${builderTeamIdx+1}`} · ${t.roster.length}/${ROSTER_SIZE}`;
 const q=(document.getElementById("builderPlayerSearch")?.value||"").trim().toLowerCase();const pos=document.getElementById("builderPlayerPos")?.value||"ALL";
 const rosterNames=new Set((t.roster||[]).map(p=>normalizeName(p.name)));
 const results=DATA.filter(p=>p.active!==false&&!rosterNames.has(normalizeName(p.name))&&(pos==="ALL"||p.pos===pos)&&(!q||p.name.toLowerCase().includes(q))).sort((a,b)=>(a.adp??999)-(b.adp??999)||a.name.localeCompare(b.name)).slice(0,60);
 const rr=document.getElementById("builderPlayerResults");if(rr)rr.innerHTML=results.length?results.map(p=>`<div class="builder-player"><div class="bp-main"><b>${escHtml(p.name)}</b><span>${p.pos} · ${p.team||"FA"} · ${p.rookie?"ROOKIE · ":""}${p.adp&&p.adp<900?`ADP ${p.adp}`:"Player pool"}</span></div><button class="secondary" data-builder-add="${encodeURIComponent(p.name)}">ADD</button></div>`).join(""):q?`<div class="builder-empty">No matching player. Use Add Custom below.</div>`:`<div class="builder-empty">Start typing to search the full player pool.</div>`;
 const rg=document.getElementById("builderRosterGrid");if(rg){const slots=["QB","RB","RB","WR","WR","TE","DEF","K"];const used=new Set();const rows=[];slots.forEach((slot,i)=>{const p=(t.roster||[]).find(x=>x.pos===slot&&!used.has(x.name));if(p){used.add(p.name);rows.push({slot:slot+(slots.slice(0,i).filter(x=>x===slot).length?" "+(slots.slice(0,i).filter(x=>x===slot).length+1):""),p});}else rows.push({slot:slot+(slots.slice(0,i).filter(x=>x===slot).length?" "+(slots.slice(0,i).filter(x=>x===slot).length+1):""),p:null});});(t.roster||[]).filter(p=>!used.has(p.name)).forEach(p=>rows.push({slot:"BENCH",p}));rg.innerHTML=rows.map(x=>`<div class="builder-slot"><div class="bs-main"><b>${x.slot}: ${x.p?escHtml(x.p.name):"Empty"}</b><span>${x.p?`${x.p.pos} · ${x.p.team||"FA"}${x.p.rookie?" · Rookie":""}`:"Available spot"}</span></div>${x.p?`<button class="ghost" data-builder-remove="${encodeURIComponent(x.p.name)}">REMOVE</button>`:""}</div>`).join("")||`<div class="builder-empty">No players entered yet.</div>`;}
 const filled=ts.filter(x=>(x.roster||[]).length>0).length;const total=ts.reduce((n,x)=>n+(x.roster||[]).length,0);const prog=document.getElementById("builderLeagueProgress");if(prog)prog.innerHTML=`<div class="progressrow"><b>${filled}/12 teams started</b><span>${total}/${12*ROSTER_SIZE} player slots</span></div><div class="progressbar"><i style="width:${Math.min(100,total/(12*ROSTER_SIZE)*100)}%"></i></div><div class="mini-list">${ts.map((x,i)=>`<span class="mini-pill">${escHtml(x.name||`Team ${i+1}`)} · ${(x.roster||[]).length}/${ROSTER_SIZE}</span>`).join("")}</div>`;
}
function builderAddPlayer(name){const t=teams[builderTeamIdx];if(!t)return;const p=DATA.find(x=>normalizeName(x.name)===normalizeName(decodeURIComponent(name)));if(!p)return;if((t.roster||[]).some(x=>normalizeName(x.name)===normalizeName(p.name)))return showToast("Player already on this roster");if(teams.some((x,i)=>i!==builderTeamIdx&&(x.roster||[]).some(p2=>normalizeName(p2.name)===normalizeName(p.name))))return showToast("Player is already assigned to another team");if((t.roster||[]).length>=ROSTER_SIZE)return showToast("Roster is full — remove a player first");t.roster=t.roster||[];t.roster.push({...p,manualRoster:true});drafted.add(p.name);recordRosterTransaction("ADD",builderTeamIdx,p,"manual roster entry");saveState();builderRender();render();showToast(`${p.name} added to ${t.name}`)}
function builderRemovePlayer(name){const t=teams[builderTeamIdx];if(!t)return;const decoded=decodeURIComponent(name);const removed=(t.roster||[]).find(p=>normalizeName(p.name)===normalizeName(decoded));t.roster=(t.roster||[]).filter(p=>normalizeName(p.name)!==normalizeName(decoded));if(removed)recordRosterTransaction("DROP",builderTeamIdx,removed,"manual roster removal");drafted=new Set(teams.flatMap(x=>(x.roster||[]).map(p=>p.name)));saveState();builderRender();render();showToast(`${decoded} removed`)}
function builderAddCustom(){const name=document.getElementById("customPlayerName")?.value.trim();const pos=document.getElementById("customPlayerPos")?.value;const team=(document.getElementById("customPlayerTeam")?.value.trim().toUpperCase()||"FA");if(!name)return showToast("Enter a player name");if(DATA.some(x=>normalizeName(x.name)===normalizeName(name)))return builderAddPlayer(encodeURIComponent(name));const p={name,pos,team,adp:999,espn:999,sleeper:999,fp:999,walter:999,tier:"Custom",active:true,custom:true};DATA.push(p);builderAddPlayer(encodeURIComponent(name));document.getElementById("customPlayerName").value="";document.getElementById("customPlayerTeam").value=""}
function builderClearTeam(){const t=teams[builderTeamIdx];if(!t)return;if(!confirm(`Clear ${t.name}'s roster?`))return;const removedCount=(t.roster||[]).length;(t.roster||[]).forEach(p=>recordRosterTransaction("DROP",builderTeamIdx,p,"team cleared"));t.roster=[];drafted=new Set(teams.flatMap(x=>(x.roster||[]).map(p=>p.name)));saveState();builderRender();render();showToast("Team roster cleared")}
document.getElementById("saveAllTeamNames")?.addEventListener("click",()=>{teams.forEach((t,i)=>{const v=document.getElementById("teamNameInput"+i)?.value.trim();if(v&&v!==t.name){const old=t.name;t.name=v;activityLog.unshift({id:Date.now()+Math.random(),timestamp:Date.now(),type:"TEAM RENAME",team:v,teamIdx:i,player:"",details:`${old} → ${v}`});}});saveState();render();renderTeamNames();renderLeagueActivity();showToast("All team names saved")});
document.getElementById("rosterTeamSelect")?.addEventListener("change",e=>{builderTeamIdx=Number(e.target.value)||0;builderRender()});
document.getElementById("builderTeamNameSave")?.addEventListener("click",()=>{const t=teams[builderTeamIdx];const v=document.getElementById("builderTeamName")?.value.trim();if(t&&v){const old=t.name;t.name=v;activityLog.unshift({id:Date.now()+Math.random(),timestamp:Date.now(),type:"TEAM RENAME",team:v,teamIdx:builderTeamIdx,player:"",details:`${old} → ${v}`});saveState();builderRender();render();renderLeagueActivity();showToast("Team name saved")}});
document.getElementById("builderPlayerSearch")?.addEventListener("input",builderRender);document.getElementById("builderPlayerPos")?.addEventListener("change",builderRender);document.getElementById("customPlayerAdd")?.addEventListener("click",builderAddCustom);document.getElementById("builderClearTeam")?.addEventListener("click",builderClearTeam);
document.addEventListener("click",e=>{const a=e.target.closest("[data-builder-add]");if(a)builderAddPlayer(a.dataset.builderAdd);const r=e.target.closest("[data-builder-remove]");if(r)builderRemovePlayer(r.dataset.builderRemove)});

/* ---------- FantasyPros direct API / import ---------- */
function setFPStatus(msg){const el=document.getElementById("fantasyProsSyncStatus");if(el)el.textContent=msg;}
async function syncFantasyPros(){
 fantasyProsApiKey=(document.getElementById("fantasyProsApiKey")?.value||fantasyProsApiKey||"").trim();
 if(!fantasyProsApiKey){setFPStatus("Enter your FantasyPros API key, or use Import JSON/CSV.");return;}
 setFPStatus("Syncing FantasyPros players, rankings and current-week projections…");
 try{
   const base="https://api.fantasypros.com/public/v2/json";
   const headers={"Accept":"application/json","x-api-key":fantasyProsApiKey};
   const [playersRes,rankRes,projRes]=await Promise.all([
     fetch(`${base}/nfl/players`,{headers,cache:"no-store"}),
     fetch(`${base}/nfl/2026/consensus-rankings?position=ALL&scoring=PPR&type=ADP`,{headers,cache:"no-store"}),
     fetch(`${base}/nfl/2026/projections?week=${plannerWeek}&scoring=PPR&positions=QB:RB:WR:TE:DST:K`,{headers,cache:"no-store"})
   ]);
   for(const r of [playersRes,rankRes,projRes])if(!r.ok)throw new Error(`FantasyPros HTTP ${r.status}${r.status===401?" — API key rejected or not activated":r.status===403?" — API access is not enabled for this key":""}`);
   const [players,rankings,projections]=await Promise.all([playersRes.json(),rankRes.json(),projRes.json()]);
   let added=0,updated=0;
   const byName=new Map(DATA.map(p=>[normalizeName(p.name),p]));
   (players.players||[]).forEach(x=>{const name=x.player_name||x.name;if(!name)return;let p=byName.get(normalizeName(name));if(!p){p={name,pos:String(x.position_id||x.position||"WR").toUpperCase(),team:x.team_id||"FA",adp:999,espn:999,sleeper:999,fp:999,walter:999,tier:"Waiver",active:true};DATA.push(p);byName.set(normalizeName(name),p);added++;}else updated++;p.pos=String(x.position_id||p.pos||"WR").toUpperCase();p.team=x.team_id||p.team||"FA";p.fpId=x.player_id||x.fpid||p.fpId;if(x.rank_adp_ppr!=null)p.adp=Number(x.rank_adp_ppr);else if(x.rank_adp!=null)p.adp=Number(x.rank_adp);});
   (rankings.players||[]).forEach(x=>{const p=byName.get(normalizeName(x.player_name||x.name));if(!p)return;if(x.rank_ecr!=null)p.fp=Number(x.rank_ecr);if(x.rank_adp_ppr!=null)p.adp=Number(x.rank_adp_ppr);else if(x.rank_adp!=null)p.adp=Number(x.rank_adp);if(x.tier!=null)p.fpTier=x.tier;});
   const norm=normalizeProjectionResponse(projections,plannerWeek);weeklyProjectionData[plannerWeek]=norm;projectionCacheMeta[plannerWeek]={source:"FantasyPros",scoring:"PPR",week:plannerWeek,engine:PROJECTION_ENGINE_VERSION,timestamp:new Date().toISOString()};
   hydrateRosterPlayersFromData();
   const audit=rosterProjectionAudit(plannerWeek);
   fantasyProsSyncState={status:"done",timestamp:Date.now(),players:(players.players||[]).length,rankings:(rankings.players||[]).length,projections:norm.count,rostered:audit.rostered.length,rosteredMatched:audit.matched.length,rosteredMissing:audit.missing.length};
   projectionSyncState={status:"done",week:plannerWeek,timestamp:new Date().toISOString(),count:norm.count,source:"FantasyPros API",engine:PROJECTION_ENGINE_VERSION};
   saveState();render();setFPStatus(`✓ Synced ${fantasyProsSyncState.players} players · ${fantasyProsSyncState.rankings} rankings · ${fantasyProsSyncState.projections} Week ${plannerWeek} projections. Added ${added} players.`);
   showToast("FantasyPros data refreshed");
 }catch(e){fantasyProsSyncState={status:"error",timestamp:Date.now(),error:String(e.message||e)};saveState();setFPStatus(`⚠️ FantasyPros sync failed: ${e.message||e}. Use Import JSON/CSV if your plan does not provide API access.`);showToast("FantasyPros sync failed");}
}
function importFantasyProsPayload(json){
 const rows=json?.projections?.players||json?.players||json?.data?.players||[];
 const norm=normalizeProjectionResponse(json,plannerWeek);
 if(norm.count)weeklyProjectionData[plannerWeek]=norm;
  if(norm.count)projectionCacheMeta[plannerWeek]={source:"FantasyPros",scoring:"PPR",week:plannerWeek,engine:PROJECTION_ENGINE_VERSION,timestamp:new Date().toISOString()};
 let added=0; const byName=new Map(DATA.map(p=>[normalizeName(p.name),p]));
 rows.forEach(x=>{const name=x.name||x.player_name;if(!name)return;let p=byName.get(normalizeName(name));if(!p){p={name,pos:String(x.position_id||x.pos||"WR").toUpperCase(),team:x.team_id||x.team||"FA",adp:999,espn:999,sleeper:999,fp:999,walter:999,tier:"Waiver",active:true};DATA.push(p);byName.set(normalizeName(name),p);added++;}if(x.team_id)p.team=x.team_id;if(x.position_id)p.pos=x.position_id;if(x.stats?.points_ppr!=null)p.fpProj=Number(x.stats.points_ppr);});
 hydrateRosterPlayersFromData();
 const audit=rosterProjectionAudit(plannerWeek);
 projectionSyncState={status:norm.count?"done":"error",week:plannerWeek,timestamp:new Date().toISOString(),count:norm.count,source:"FantasyPros import",engine:PROJECTION_ENGINE_VERSION,rostered:audit.rostered.length,rosteredMatched:audit.matched.length,rosteredMissing:audit.missing.length};
 fantasyProsSyncState={status:norm.count?"done":"error",timestamp:Date.now(),projections:norm.count};
 saveState();render();setFPStatus(`✓ Imported ${norm.count} Week ${plannerWeek} projections${added?` and added ${added} players`:""}.`);
}
function importFantasyProsJSON(file){const r=new FileReader();r.onload=()=>{try{importFantasyProsPayload(JSON.parse(r.result));}catch(e){setFPStatus(`⚠️ Invalid FantasyPros JSON: ${e.message||e}`);}};r.readAsText(file);}
function importFantasyProsCSV(file){const r=new FileReader();r.onload=()=>{const lines=String(r.result).split(/\r?\n/).filter(Boolean);if(lines.length<2){setFPStatus("⚠️ CSV is empty.");return;}const headers=lines[0].split(",").map(x=>x.trim().toLowerCase());const idx=n=>headers.findIndex(h=>h===n||h.includes(n));const nameI=idx("player")>=0?idx("player"):idx("name");const ptsI=idx("fpts")>=0?idx("fpts"):idx("points");if(nameI<0||ptsI<0){setFPStatus("⚠️ CSV needs Player/Name and FPTS/Points columns.");return;}const norm={};lines.slice(1).forEach(line=>{const cols=line.split(",");const name=cols[nameI]?.trim();const pts=Number(cols[ptsI]);if(name&&Number.isFinite(pts))norm[projectionKey(name)]=pts;});if(Object.keys(norm).length<20){setFPStatus(`⚠️ Only ${Object.keys(norm).length} usable projection rows found.`);return;}weeklyProjectionData[plannerWeek]={byName:norm,byId:{},count:Object.keys(norm).length,week:plannerWeek,scoring:"PPR",source:"FantasyPros",engine:PROJECTION_ENGINE_VERSION};projectionCacheMeta[plannerWeek]={source:"FantasyPros",scoring:"PPR",week:plannerWeek,engine:PROJECTION_ENGINE_VERSION,timestamp:new Date().toISOString()};hydrateRosterPlayersFromData();const audit=rosterProjectionAudit(plannerWeek);projectionSyncState={status:"done",week:plannerWeek,timestamp:new Date().toISOString(),count:Object.keys(norm).length,source:"FantasyPros CSV",rostered:audit.rostered.length,rosteredMatched:audit.matched.length,rosteredMissing:audit.missing.length};fantasyProsSyncState={status:"done",timestamp:Date.now(),projections:Object.keys(norm).length};saveState();render();setFPStatus(`✓ Imported ${Object.keys(norm).length} Week ${plannerWeek} PPR projection rows from CSV.`);};r.readAsText(file);}
